// The League outlook charts: position bars, the strength scatter, team radars and the depth chart.
import {POSITIONS as LEAGUE_POSITIONS,positionRadar} from '../../league.js';
import {S} from '../state.js';
import {POSITION_COLORS,esc,fmt,league,ordinal,pname} from '../core.js';

export function positionBars(rows,pick,total,unit){
 const max=Math.max(1,...rows.map(total)),used=LEAGUE_POSITIONS.filter(p=>rows.some(r=>(pick(r)?.[p]||0)>0));
 return `<div class="strength-legend" aria-hidden="true">${used.map(p=>`<span><i style="background:${POSITION_COLORS[p]}"></i>${p}</span>`).join('')}</div><div class="strength-chart" role="list">${rows.map((r,i)=>`<div class="strength-row ${r.mine?'mine':''}" role="listitem" aria-label="${esc(r.team)}: ${fmt(total(r))} ${unit}"><div class="strength-name"><span class="muted">${i+1}</span> ${esc(r.team)}</div><div class="strength-track"><div class="strength-bar" style="width:${Math.max(0,total(r))/max*100}%">${used.filter(p=>(pick(r)?.[p]||0)>0).map(p=>`<i style="flex:${pick(r)[p]};background:${POSITION_COLORS[p]}" title="${esc(r.team)} · ${p} ${fmt(pick(r)[p])} ${unit}"></i>`).join('')}</div><strong>${fmt(total(r))}</strong></div></div>`).join('')}</div>`;
}
export function strengthScatter(rows){
 const points=rows.filter(r=>r.roster&&r.average!==null);if(points.length<3)return '';
 const W=640,H=340,pad={l:46,r:16,t:16,b:40},xs=points.map(r=>r.roster.points),ys=points.map(r=>r.average);
 const span=list=>{const lo=Math.min(...list),hi=Math.max(...list),room=Math.max(4,(hi-lo)*.12);return [lo-room,hi+room]},[x0,x1]=span(xs),[y0,y1]=span(ys);
 const x=v=>pad.l+(v-x0)/(x1-x0)*(W-pad.l-pad.r),y=v=>H-pad.b-(v-y0)/(y1-y0)*(H-pad.t-pad.b),ticks=(lo,hi)=>{const step=[5,10,20,25,50].find(s=>(hi-lo)/s<=6)||100;return Array.from({length:Math.floor(hi/step)-Math.ceil(lo/step)+1},(_,i)=>(Math.ceil(lo/step)+i)*step)};
 const mx=xs.reduce((s,v)=>s+v,0)/xs.length,my=ys.reduce((s,v)=>s+v,0)/ys.length;
 // Labels take the first free spot around their dot. One with no room is left to the tooltip.
 const boxes=points.map(r=>({x0:x(r.roster.points)-8,x1:x(r.roster.points)+8,y0:y(r.average)-8,y1:y(r.average)+8})),labels=new Map();
 for(const r of [...points].sort((a,b)=>b.mine-a.mine)){
  const name=r.team.length>16?r.team.slice(0,15)+'…':r.team,w=name.length*6.4+4,cx=x(r.roster.points),cy=y(r.average);
  const spot=[[cx+10,cy+4,'start'],[cx-10,cy+4,'end'],[cx,cy-11,'middle'],[cx,cy+19,'middle']].map(([tx,ty,anchor])=>({tx,ty,anchor,x0:anchor==='start'?tx:anchor==='end'?tx-w:tx-w/2,y0:ty-10})).map(b=>({...b,x1:b.x0+w,y1:b.y0+13})).find(b=>b.x0>=pad.l&&b.x1<=W-pad.r&&b.y0>=pad.t&&b.y1<=H-pad.b&&!boxes.some(o=>o!==boxes[points.indexOf(r)]&&b.x0<o.x1&&b.x1>o.x0&&b.y0<o.y1&&b.y1>o.y0));
  if(spot){boxes.push(spot);labels.set(r,`<text x="${spot.tx}" y="${spot.ty}" text-anchor="${spot.anchor}">${esc(name)}</text>`)}
 }
 const label=r=>labels.get(r)||'';
 return `<figure class="scatter"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Each team’s points per week so far against what its roster projects to score"><g class="scatter-grid">${ticks(x0,x1).map(t=>`<line x1="${x(t)}" x2="${x(t)}" y1="${pad.t}" y2="${H-pad.b}"/><text x="${x(t)}" y="${H-pad.b+16}" text-anchor="middle">${t}</text>`).join('')}${ticks(y0,y1).map(t=>`<line x1="${pad.l}" x2="${W-pad.r}" y1="${y(t)}" y2="${y(t)}"/><text x="${pad.l-8}" y="${y(t)+4}" text-anchor="end">${t}</text>`).join('')}</g><g class="scatter-mean"><line x1="${x(mx)}" x2="${x(mx)}" y1="${pad.t}" y2="${H-pad.b}"/><line x1="${pad.l}" x2="${W-pad.r}" y1="${y(my)}" y2="${y(my)}"/></g><text class="scatter-corner" x="${pad.l+6}" y="${pad.t+12}">Scoring above their roster</text><text class="scatter-corner" x="${W-pad.r-6}" y="${pad.t+12}" text-anchor="end">Strong and showing it</text><text class="scatter-corner" x="${pad.l+6}" y="${H-pad.b-8}">Weak so far, weak ahead</text><text class="scatter-corner" x="${W-pad.r-6}" y="${H-pad.b-8}" text-anchor="end">Better than the results</text><text class="scatter-axis" x="${(W+pad.l-pad.r)/2}" y="${H-4}" text-anchor="middle">Roster projection, points a week</text><text class="scatter-axis" transform="translate(12 ${(H-pad.b+pad.t)/2}) rotate(-90)" text-anchor="middle">Scored so far, points a week</text>${points.map(r=>`<g class="scatter-dot ${r.mine?'mine':''}"><title>${esc(r.team)} · scored ${fmt(r.average)} a week · roster projects ${fmt(r.roster.points)}</title><circle cx="${x(r.roster.points)}" cy="${y(r.average)}" r="6"/>${label(r)}</g>`).join('')}</svg></figure>`;
}
// Team shapes: each team's points by position against the league average. Your team is always ink;
// up to four others take a color for as long as they stay picked, so a color never changes hands.
export const RADAR_COLORS=['#2a78d6','#e34948','#eda100','#4a3aa7'];
export function radarColor(r){return r.mine?'var(--dark)':RADAR_COLORS[S.radarPicks.get(r.rosterId)]}
export function teamRadar(o,pick,unit){
 const l=league();if(S.radarLeague!==l.league_id){S.radarLeague=l.league_id;S.radarPicks=new Map(o.rows.filter(r=>r.mine).map(r=>[r.rosterId,-1]));S.radarAll=false}
 const radar=positionRadar(o.rows,pick);if(!radar)return '<p class="muted small">Not enough positions with points to draw a shape yet.</p>';
 const by=new Map(o.rows.map(r=>[r.rosterId,r])),picked=radar.teams.filter(t=>S.radarPicks.has(t.rosterId)),rest=radar.teams.filter(t=>!S.radarPicks.has(t.rosterId));
 const W=440,H=400,cx=W/2,cy=H/2+4,R=138,n=radar.axes.length,angle=i=>-Math.PI/2+i*2*Math.PI/n;
 const reach=v=>R*(.06+.94*Math.max(0,Math.min(1,(v-radar.low)/(radar.high-radar.low)))),point=(i,v)=>[cx+Math.cos(angle(i))*reach(v),cy+Math.sin(angle(i))*reach(v)],path=ratios=>ratios.map((v,i)=>point(i,v).map(c=>c.toFixed(1)).join(',')).join(' ');
 const rings=[radar.low,(radar.low+1)/2,1,(radar.high+1)/2,radar.high];
 const svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Points by position against the league average for ${esc(picked.map(t=>by.get(t.rosterId).team).join(', ')||'no team')}${S.radarAll?' and every other team':''}"><g class="radar-grid">${rings.map(v=>`<polygon class="${v===1?'radar-average':''}" points="${path(radar.axes.map(()=>v))}"/>`).join('')}${radar.axes.map((a,i)=>{const [x,y]=point(i,radar.high);return `<line x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>`}).join('')}${rings.filter((v,i)=>i%2===0).map(v=>{const half=angle(0)+Math.PI/n,d=reach(v)*Math.cos(Math.PI/n);return `<text x="${(cx+Math.cos(half)*d+3).toFixed(1)}" y="${(cy+Math.sin(half)*d-3).toFixed(1)}">${v===1?'avg':`${Math.round(v*100)}%`}</text>`}).join('')}</g>${radar.axes.map((a,i)=>{const [x,y]=[cx+Math.cos(angle(i))*(R+22),cy+Math.sin(angle(i))*(R+22)],anchor=Math.abs(Math.cos(angle(i)))<.3?'middle':Math.cos(angle(i))>0?'start':'end';return `<text class="radar-axis" x="${x.toFixed(1)}" y="${(y+(Math.sin(angle(i))>.3?8:Math.sin(angle(i))<-.3?-6:4)).toFixed(1)}" text-anchor="${anchor}">${a.position}<tspan class="radar-axis-note" dx="5">avg ${fmt(a.average)}</tspan></text>`}).join('')}${S.radarAll?rest.map(t=>`<polygon class="radar-ghost" points="${path(t.ratios)}"><title>${esc(by.get(t.rosterId).team)}</title></polygon>`).join(''):''}${[...picked].sort((a,b)=>by.get(a.rosterId).mine-by.get(b.rosterId).mine).map(t=>{const r=by.get(t.rosterId),color=radarColor(r);return `<g class="radar-team" style="--team:${color}"><polygon points="${path(t.ratios)}"/>${t.ratios.map((v,i)=>{const [x,y]=point(i,v);return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4"><title>${esc(r.team)} · ${radar.axes[i].position} ${fmt(t.values[i])} ${unit} · ${Math.round(v*100)}% of the league average${v<radar.low||v>radar.high?' (off the scale, drawn at the edge)':''}</title></circle>`}).join('')}</g>`}).join('')}</svg>`;
 const chips=`<div class="radar-chips" role="group" aria-label="Teams to draw">${[...o.rows].sort((a,b)=>b.mine-a.mine||a.powerRank-b.powerRank).filter(r=>pick(r)).map(r=>{const on=S.radarPicks.has(r.rosterId);return `<button class="radar-chip ${on?'active':''}" data-radar-team="${r.rosterId}" aria-pressed="${on}"><i style="background:${on?radarColor(r):'transparent'}"></i>${esc(r.team)}</button>`}).join('')}</div><div class="radar-actions"><button class="filter ${S.radarAll?'active':''}" data-radar-all aria-pressed="${S.radarAll}">Everyone in the background</button>${S.radarPicks.size>1||!picked.some(t=>by.get(t.rosterId).mine)?'<button class="inline-btn" data-radar-reset>Just my team</button>':''}</div>`;
 const table=picked.length?`<div class="table-wrap"><table class="radar-table"><thead><tr><th scope="col">POS.</th>${picked.map(t=>`<th scope="col"><i style="background:${radarColor(by.get(t.rosterId))}"></i>${esc(by.get(t.rosterId).team)}</th>`).join('')}<th scope="col">LEAGUE AVG.</th></tr></thead><tbody>${radar.axes.map((a,i)=>`<tr><th scope="row">${a.position}</th>${picked.map(t=>`<td class="num"><strong>${fmt(t.values[i])}</strong> <span class="${t.ratios[i]>=1.1?'gain':t.ratios[i]<=.9?'attention':'muted'} small">${t.ratios[i]>1?'+':''}${Math.round((t.ratios[i]-1)*100)}%</span></td>`).join('')}<td class="num muted">${fmt(a.average)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Pick a team to see its numbers.</p>';
 return `<div class="radar-layout"><figure class="radar">${svg}</figure><div class="radar-side"><p class="muted small">Pick up to four teams to lay over yours.</p>${chips}${table}</div></div>`;
}
export function depthTable(o,chart,unit){
 if(!chart)return '';
 const short=id=>{const p=S.data.players[id];return p?.position==='DEF'?(p.team||pname(id)):p?.first_name&&p?.last_name?`${p.first_name[0]}. ${p.last_name}`:pname(id)};
 return `<div class="panel table-wrap defense-table-wrap league-panel flush"><table class="week-table season-table depth-table"><thead><tr><th scope="col">TEAM</th>${chart.columns.map(c=>`<th scope="col" title="League average ${fmt(c.average)} ${unit}">${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${[...o.rows].sort((a,b)=>a.powerRank-b.powerRank).map(r=>`<tr class="${r.mine?'mine':''}"><th scope="row" class="season-player"><strong>${esc(r.team)}</strong>${r.mine?' <span class="pill you">YOU</span>':''}</th>${chart.cells[r.rosterId].map((c,i)=>{const inner=c?`<strong>${fmt(c.points)}</strong><div class="small">${esc(short(c.id))}</div>`:'—',hint=c?`${pname(c.id)} · ${ordinal(c.rank)} of ${c.of} at ${chart.columns[i].label} · league average ${fmt(chart.columns[i].average)}`:'Nobody to play here';return `<td class="defense-cell depth-cell ${c?`defense-${c.tone}`:'muted'}" title="${esc(hint)}${r.mine?' · Click to look for an upgrade':''}">${r.mine?`<button class="depth-target" data-depth-target="${esc(chart.columns[i].position)}" aria-label="Find trades for a ${esc(chart.columns[i].position)}. ${esc(hint)}">${inner}</button>`:inner}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
}
